const CACHE='african-safari-compass-v13';
const ASSETS=['./','./index.html','./styles.css','./map.css','./africa.css','./mobile-app.css','./catalog.css','./wildlife.css','./trip.css','./botswana.css','./safety.css','./real-map.css','./map-fixes.css','./route-actions.css','./native-bridge.js','./app.js','./real-map.js','./botswana.js','./catalog.js','./wildlife.js','./mobile.js','./safety.js','./map-fixes.js','./route-actions.js','./manifest.webmanifest','./assets/app-icon.svg','./assets/safari-dawn.png'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET')return;const sameOrigin=new URL(event.request.url).origin===location.origin;if(!sameOrigin){event.respondWith(caches.match(event.request).then(cached=>cached||fetch(event.request).then(response=>{if(response.ok||response.type==='opaque'){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response})));return}event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response}).catch(()=>caches.match(event.request).then(cached=>cached||caches.match('./index.html'))))});
